<script setup lang="ts">
import { Head, Link, useForm } from '@inertiajs/vue3'
import { computed, ref } from 'vue'
import AuthenticatedLayout from '../../Layouts/AuthenticatedLayout.vue'
import InventorySkuCombobox from './components/InventorySkuCombobox.vue'

type Item={id:number;product:{id:number;sku:string;name:string};quantity_on_hand:number;quantity_reserved:number;quantity_available:number;stock_status:'out_of_stock'|'low_stock'|'in_stock';stock_status_label:string;inbound_at:string|null;stay_days:number|null;location:string|null;standard_qoh:number|null;expected_restock_qty:number;replenishment:{policy_status:'unconfigured'|'no_demand'|'reorder'|'healthy';policy_label:string;shipped_90d_qty:number;days_of_cover:number|null;recommended_restock_qty:number|null}}
type W={id:number;slug:string;public_slug:string;code:string;name:string;name_en:string|null;role_label:string;is_fulfillment_warehouse:boolean;is_inventory_only_warehouse:boolean;country_code:string|null;address_line1:string|null;address_line2:string|null;city:string|null;state_region:string|null;postal_code:string|null;timezone:string|null;type:string;ownership_type:'owned'|'external';is_domestic:boolean;is_active:boolean;priority:number;fulfillment_available_on:string|null;fulfillment_state:'preparing'|'awaiting_inventory'|'ready';fulfillment_state_label:string;replenishment_lead_time_days:number|null;replenishment_safety_stock_days:number|null;replenishment_target_cover_days:number|null;billing_markdown:string|null;service_regions:string[];last_inventory_sync_at:string|null;inventories:Item[]}
type ClearanceProduct={id:number;product:{id:number;sku:string;name:string};priority:number;quantity_on_hand:number|null;quantity_reserved:number|null;quantity_available:number|null;status:'available'|'out_of_stock'|'unknown';status_label:string}
type ClearanceCandidate={product_id:number;sku:string;name:string;quantity_available:number;already_clearance:boolean}
const props=defineProps<{warehouse:W;clearanceProducts:ClearanceProduct[];clearanceCandidates:ClearanceCandidate[];canOperate:boolean;canManage:boolean}>()
const warehousePath=`/inventory/${props.warehouse.public_slug||props.warehouse.slug}`
const breadcrumbs=[{label:'YBY ERP',href:'/dashboard'},{label:'库存',href:'/inventory'},{label:'仓库清单',href:'/inventory/list'},props.warehouse.name]
const query=ref('');const statusFilter=ref<'all'|'in_stock'|'low_stock'|'out_of_stock'>('all');const productTab=ref<'inventory'|'clearance'>('inventory');const clearanceQuery=ref('')
const meta=useForm({name:props.warehouse.name,code:props.warehouse.code,country_code:props.warehouse.country_code||'',address_line1:props.warehouse.address_line1||'',address_line2:props.warehouse.address_line2||'',city:props.warehouse.city||'',state_region:props.warehouse.state_region||'',postal_code:props.warehouse.postal_code||'',timezone:props.warehouse.timezone||'',type:props.warehouse.type,ownership_type:props.warehouse.ownership_type,is_domestic:props.warehouse.is_domestic,is_active:props.warehouse.is_active,priority:props.warehouse.priority,fulfillment_available_on:props.warehouse.fulfillment_available_on||'',replenishment_lead_time_days:props.warehouse.replenishment_lead_time_days,replenishment_safety_stock_days:props.warehouse.replenishment_safety_stock_days,replenishment_target_cover_days:props.warehouse.replenishment_target_cover_days})
const billing=useForm({billing_markdown:props.warehouse.billing_markdown||''});const regions=useForm({country_codes:props.warehouse.service_regions.join(', ')} as any);const stock=useForm({product_id:null as number|null,sku:'',quantity_on_hand:0,quantity_reserved:0,inbound_at:'',location:'',standard_qoh:null as number|null,expected_restock_qty:0});const clearance=useForm({product_ids:[] as number[]})
const filteredItems=computed(()=>props.warehouse.inventories.filter(i=>(statusFilter.value==='all'||i.stock_status===statusFilter.value)&&(!query.value||`${i.product.sku} ${i.product.name} ${i.location||''}`.toLowerCase().includes(query.value.toLowerCase()))))
const kpis=computed(()=>({skus:props.warehouse.inventories.length,onHand:props.warehouse.inventories.reduce((n,i)=>n+i.quantity_on_hand,0),available:props.warehouse.inventories.reduce((n,i)=>n+i.quantity_available,0),low:props.warehouse.inventories.filter(i=>i.stock_status==='low_stock').length,out:props.warehouse.inventories.filter(i=>i.stock_status==='out_of_stock').length}))
const lastSync=computed(()=>props.warehouse.last_inventory_sync_at?new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(props.warehouse.last_inventory_sync_at)):'尚未同步')
const warehouseAddress=computed(()=>[props.warehouse.address_line1,props.warehouse.address_line2,props.warehouse.city,props.warehouse.state_region,props.warehouse.postal_code,props.warehouse.country_code].filter(Boolean).join(', ')||'地址未填写')
const filteredClearanceCandidates=computed(()=>props.clearanceCandidates.filter(c=>!c.already_clearance&&(!clearanceQuery.value||`${c.sku} ${c.name}`.toLowerCase().includes(clearanceQuery.value.toLowerCase()))))
const saveMeta=()=>meta.patch(warehousePath);const saveBilling=()=>billing.patch(`${warehousePath}/billing`);const saveRegions=()=>{const codes=String(regions.country_codes||'').split(',').map(x=>x.trim().toUpperCase()).filter(Boolean);regions.transform(()=>({country_codes:codes})).patch(`${warehousePath}/regions`,{onFinish:()=>regions.defaults()})};const addStock=()=>stock.transform(d=>({product_id:d.product_id,quantity_on_hand:d.quantity_on_hand,quantity_reserved:d.quantity_reserved,inbound_at:d.inbound_at||null,location:d.location||null,standard_qoh:d.standard_qoh,expected_restock_qty:d.expected_restock_qty})).post(`${warehousePath}/stock`,{onSuccess:()=>stock.reset()});const quick=(item:Item)=>{const f=useForm({quantity_on_hand:item.quantity_on_hand,quantity_reserved:item.quantity_reserved,inbound_at:item.inbound_at||'',location:item.location||'',standard_qoh:item.standard_qoh,expected_restock_qty:item.expected_restock_qty});f.patch(`${warehousePath}/stock/${item.id}`)};const addClearance=()=>clearance.post(`${warehousePath}/clearance`,{preserveScroll:true,onSuccess:()=>clearance.reset('product_ids')});const updateClearancePriority=(item:ClearanceProduct,event:Event)=>useForm({priority:Number((event.target as HTMLInputElement).value)}).patch(`${warehousePath}/clearance/${item.id}`,{preserveScroll:true});const removeClearance=(item:ClearanceProduct)=>useForm({}).delete(`${warehousePath}/clearance/${item.id}`,{preserveScroll:true})
</script>
<template>
<Head :title="`${warehouse.name} · YBY ERP`"/>
<AuthenticatedLayout :title="warehouse.name" :breadcrumbs="breadcrumbs">
<section class="warehouse-page">
<header class="warehouse-hero">
  <div><p class="eyebrow">Inventory OS · Warehouse</p><div class="title-line"><h2>{{warehouse.name}}</h2><span class="warehouse-code">{{warehouse.code}}</span><span class="state-pill" :class="warehouse.fulfillment_state">{{warehouse.fulfillment_state_label}}</span></div><p class="subtitle">{{warehouse.name_en||warehouse.code}} · {{warehouse.role_label}} · {{warehouseAddress}}</p></div>
  <div class="hero-actions"><Link class="button ghost" href="/inventory/list">仓库清单</Link><Link class="button primary" href="/inventory/sync">导入库存</Link></div>
</header>
<div class="kpi-grid">
  <article><span>库存 SKU</span><strong>{{kpis.skus}}</strong><small>当前仓库商品</small></article>
  <article><span>当前库存</span><strong>{{kpis.onHand}}</strong><small>仓库实物数量</small></article>
  <article><span>可用库存</span><strong>{{kpis.available}}</strong><small>扣除预留后</small></article>
  <article><span>库存预警</span><strong>{{kpis.low+kpis.out}}</strong><small>{{kpis.low}} 紧张 · {{kpis.out}} 无货</small></article>
  <article><span>最后同步</span><strong class="sync-time">{{lastSync}}</strong><small>最近确认库存快照</small></article>
</div>
<section class="primary-panel">
  <div class="section-heading"><div><p class="section-kicker">CURRENT INVENTORY</p><h3>目前仓库产品库存统计</h3><p>日常库存查看放在页面第一优先级；搜索 SKU、产品名称或库位即可快速定位。</p></div><div class="section-actions"><Link class="button ghost" href="/inventory/products">全部产品库存</Link><Link class="button primary" href="/inventory/sync">导入 / 更新库存</Link></div></div>
  <div class="toolbar"><div class="search"><span>⌕</span><input v-model="query" placeholder="搜索 SKU、产品或库位"></div><select v-model="statusFilter"><option value="all">全部状态</option><option value="in_stock">库存正常</option><option value="low_stock">库存紧张</option><option value="out_of_stock">无货</option></select><span class="result-count">{{filteredItems.length}} / {{warehouse.inventories.length}} SKU</span></div>
  <div class="table-shell"><table class="inventory-table"><thead><tr><th>SKU / 产品</th><th>可用库存</th><th>当前</th><th>预留</th><th>库位</th><th>最近入库</th><th>库存状态</th><th>90 天发货</th><th>建议补货</th><th v-if="canOperate"></th></tr></thead><tbody>
    <tr v-for="i in filteredItems" :key="i.id"><td><strong>{{i.product.sku}}</strong><small>{{i.product.name}}</small></td><td class="quantity">{{i.quantity_available}}</td><td>{{i.quantity_on_hand}}</td><td>{{i.quantity_reserved}}</td><td>{{i.location||'—'}}</td><td>{{i.inbound_at||'—'}}</td><td><span class="stock-badge" :class="`stock-${i.stock_status}`">{{i.stock_status_label}}</span></td><td>{{i.replenishment.shipped_90d_qty}}</td><td>{{i.replenishment.recommended_restock_qty===null?i.replenishment.policy_label:`${i.replenishment.policy_label} · ${i.replenishment.recommended_restock_qty}`}}</td><td v-if="canOperate"><button class="text-button" @click="quick(i)">保存</button></td></tr>
    <tr v-if="!filteredItems.length"><td :colspan="canOperate?10:9" class="empty">没有符合当前筛选条件的库存商品</td></tr>
  </tbody></table></div>
</section><details class="secondary-panel">
  <summary><div><p class="section-kicker">WAREHOUSE COSTS</p><strong>最近 3 个月仓库费用</strong><small>P3 接入账单导入后，在这里显示运费、操作费与仓储费。</small></div><span>展开</span></summary>
  <div class="placeholder"><div><b>费用中心将在 P3 启用</b><p>保留当前信息架构位置，不在 P0/P1 写入任何费用数据。</p></div></div>
</details>
<details class="secondary-panel">
  <summary><div><p class="section-kicker">SHIPPING RULES</p><strong>仓库运费规则</strong><small>{{billing.billing_markdown?'已配置':'尚未配置'}} · 低频配置默认折叠</small></div><span>展开</span></summary>
  <div class="details-body"><pre class="markdown">{{billing.billing_markdown||'未填写仓库计费表'}}</pre><form v-if="canManage" @submit.prevent="saveBilling"><textarea v-model="billing.billing_markdown" rows="12" placeholder="粘贴或编辑 Markdown 计费规则"></textarea><div class="form-actions"><button class="button primary">保存运费规则</button></div></form></div>
</details>
<details class="secondary-panel">
  <summary><div><p class="section-kicker">WAREHOUSE PROFILE</p><strong>仓库资料</strong><small>{{warehouse.name}} · {{warehouse.city||warehouse.country_code||'地址待补充'}} · 一次填写长期使用</small></div><span>展开</span></summary>
  <div class="details-body"><form v-if="canManage" class="profile-grid" @submit.prevent="saveMeta"><label>名称<input v-model="meta.name"></label><label>代码<input v-model="meta.code"></label><label>国家<input v-model="meta.country_code" maxlength="2"></label><label>城市<input v-model="meta.city"></label><label>州 / 省<input v-model="meta.state_region"></label><label>邮编<input v-model="meta.postal_code"></label><label class="wide">地址 1<input v-model="meta.address_line1"></label><label class="wide">地址 2<input v-model="meta.address_line2"></label><label>时区<input v-model="meta.timezone"></label><label>仓库归属<select v-model="meta.ownership_type"><option value="owned">自有仓</option><option value="external">外部仓</option></select></label><label>国内发货仓<select v-model="meta.is_domestic"><option :value="true">是</option><option :value="false">否</option></select></label><label>优先级<input v-model.number="meta.priority" type="number"></label><label>预计可发货<input v-model="meta.fulfillment_available_on" type="date"></label><label>补货周期（天）<input v-model.number="meta.replenishment_lead_time_days" type="number" min="0" max="365"></label><label>安全库存（天）<input v-model.number="meta.replenishment_safety_stock_days" type="number" min="0" max="365"></label><label>目标覆盖（天）<input v-model.number="meta.replenishment_target_cover_days" type="number" min="0" max="365"></label><label>状态<select v-model="meta.is_active"><option :value="true">启用</option><option :value="false">停用</option></select></label><div class="wide form-actions"><button class="button primary">保存仓库资料</button></div></form><p v-else>{{warehouseAddress}}</p>
  <div class="region-block"><h4>服务国家 / 地区</h4><form v-if="canManage" class="inline-form" @submit.prevent="saveRegions"><input v-model="regions.country_codes" placeholder="US, CA, DE"><button class="button ghost">保存</button></form><p v-else>{{warehouse.service_regions.join(', ')||'未配置'}}</p></div></div>
</details>
<details v-if="canOperate" class="secondary-panel"><summary><div><p class="section-kicker">MANUAL STOCK</p><strong>手工增加 / 更新产品库存</strong><small>保留原有人工库存能力，日常无需展开。</small></div><span>展开</span></summary><form class="details-body stock-grid" @submit.prevent="addStock"><label>SKU / 产品<InventorySkuCombobox v-model="stock.sku" v-model:product-id="stock.product_id"/></label><label>当前库存<input v-model.number="stock.quantity_on_hand" type="number" min="0"></label><label>预留<input v-model.number="stock.quantity_reserved" type="number" min="0"></label><label>上架时间<input v-model="stock.inbound_at" type="date"></label><label>Location<input v-model="stock.location"></label><label>Standard QoH<input v-model.number="stock.standard_qoh" type="number" min="0"></label><label>预计备货<input v-model.number="stock.expected_restock_qty" type="number" min="0"></label><button class="button primary" :disabled="!stock.product_id">保存库存</button></form></details>
<section class="clearance-section"><div class="product-tabs"><button :class="{active:productTab==='inventory'}" @click="productTab='inventory'">库存视图</button><button :class="{active:productTab==='clearance'}" @click="productTab='clearance'">清仓 / Gift 库 <span>{{clearanceProducts.length}}</span></button></div>
<div v-if="productTab==='clearance'" class="secondary-content"><div class="clearance-heading"><div><h3>清仓 / Gift 库</h3><p>加入清仓后自动成为本仓 Gift 候选；实际是否可选始终读取实时可用库存。</p></div></div><form v-if="canOperate" class="clearance-add" @submit.prevent="addClearance"><div class="clearance-picker"><input v-model="clearanceQuery" placeholder="搜索本仓库存 SKU / 商品"><div class="candidate-list"><label v-for="candidate in filteredClearanceCandidates" :key="candidate.product_id"><input v-model="clearance.product_ids" type="checkbox" :value="candidate.product_id"><strong>{{candidate.sku}}</strong><span>{{candidate.name}}</span><small>可用 {{candidate.quantity_available}}</small></label></div></div><button class="button primary" :disabled="!clearance.product_ids.length||clearance.processing">加入清仓商品</button></form><div class="table-shell"><table><thead><tr><th>SKU</th><th>商品</th><th>可用库存</th><th>Gift 优先级</th><th>状态</th><th v-if="canOperate">操作</th></tr></thead><tbody><tr v-for="item in clearanceProducts" :key="item.id"><td><strong>{{item.product.sku}}</strong></td><td>{{item.product.name}}</td><td>{{item.quantity_available??'—'}}</td><td><input class="priority-input" type="number" min="1" max="9999" :value="item.priority" :disabled="!canOperate" @change="updateClearancePriority(item,$event)"></td><td>{{item.status_label}}</td><td v-if="canOperate"><button class="text-button danger" @click="removeClearance(item)">移出</button></td></tr></tbody></table></div></div>
</section>
</section>
</AuthenticatedLayout>
</template>
